private fun buildCodeLanguageIcon(name: String, pathData: String): ImageVector =
    ImageVector.Builder(
        name = "CodeLanguage-$name",
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 24f,
        viewportHeight = 24f
    ).addPath(
        pathData = PathParser().parsePathString(pathData).toNodes(),
        fill = SolidColor(Color.Black)
    ).build()

private val codeLanguageIconCache = mutableMapOf<String, ImageVector>()

internal fun codeLanguageVectorIcon(language: String): ImageVector? {
    val pathData = codeLanguageIconPaths[language] ?: return null
    return codeLanguageIconCache.getOrPut(language) {
        buildCodeLanguageIcon(language, pathData)
    }
}
